package com.dy.artisan3d.ui.screen.products.viewimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.repository.ProductDetailRepositoryimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.launchclass ProductDetailViewModel(    private val repository: ProductDetailRepository,    private val appLang: AppLanguage,    private val productId: Int,) : ViewModel() {    private val _uiState = MutableStateFlow<ProductDetailUiState>(ProductDetailUiState.Loading)    val uiState: StateFlow<ProductDetailUiState> = _uiState.asStateFlow()    private val _selectedImageIndex = MutableStateFlow(0)    val selectedImageIndex: StateFlow<Int> = _selectedImageIndex.asStateFlow()    private val _show3DModel = MutableStateFlow(false)    val show3DModel: StateFlow<Boolean> = _show3DModel.asStateFlow()    init {        loadProductDetail()    }    fun loadProductDetail() {        viewModelScope.launch {            _uiState.value = ProductDetailUiState.Loading            repository.getProductDetail(productId, appLang.current)                .onSuccess { product ->                    _uiState.value = ProductDetailUiState.Success(product)                }                .onFailure { error ->                    _uiState.value = ProductDetailUiState.Error(                        error.message ?: "Unknown error occurred"                    )                }        }    }    fun selectImage(index: Int) {        _selectedImageIndex.value = index    }    fun toggle3DModel() {        _show3DModel.value = !_show3DModel.value    }    fun show3DModel() {        _show3DModel.value = true    }    fun hide3DModel() {        _show3DModel.value = false    }}